#!/usr/bin/env python3
"""Build a bilingual, dependency-free static site from authored Markdown.
Usage: python3 scripts/build.py
"""
import html
import json
from pathlib import Path
import re
import shutil
import subprocess
import zipfile

ROOT=Path(__file__).resolve().parents[1]
SITE=ROOT/'site'
CATALOG=json.loads((ROOT/'content/catalog.json').read_text())
MEDIA=json.loads((ROOT/'content/media.json').read_text())
def E(x):return html.escape(str(x),quote=True)
def T(x,lang):return x[lang] if isinstance(x,list) else x
def inline(text):
    s=E(text)
    s=re.sub(r'`([^`]+)`',r'<code>\1</code>',s)
    s=re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',s)
    return s
def markdown(text):
    blocks=[];paragraph=[];code=None;lines=[]
    def flush():
        if paragraph:blocks.append('<p>'+inline(' '.join(paragraph))+'</p>');paragraph.clear()
    for line in text.splitlines():
        if line.startswith('```'):
            if code is None:flush();code=[]
            else:blocks.append('<pre><code>'+E('\n'.join(code))+'</code></pre>');code=None
        elif code is not None:code.append(line)
        elif line.strip()=='[[interactive]]':flush();blocks.append('<div class="inline-lab" data-inline-lab></div>')
        elif not line.strip():flush()
        else:paragraph.append(line)
    flush();return '\n'.join(blocks)
def sections(m):
    texts=[(ROOT/f"content/modules/{m['id']}.{lang}.md").read_text() for lang in ['zh','en']]
    parts=[re.split(r'^## (.+)$',text,flags=re.M)[1:] for text in texts]
    assert len(parts[0])==len(parts[1])==14,m['id']
    out=[]
    for i in range(0,len(parts[0]),2):
        out.append({'id':f"lesson-{m['id']}-{i//2+1}",'title':[parts[l][i] for l in range(2)],'text':[parts[l][i+1].strip() for l in range(2)]})
    return out
for m in CATALOG:m['sections']=sections(m)

def url(m):return f"modules/{m['id']}-{m['slug']}/index.html"
LOGO='<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M8 9 8 23M24 9 24 23" stroke="#0f6b5c" stroke-width="1.5"/><path d="M8 9 24 9M8 23 24 23" stroke="#b78056" stroke-width="1.2" stroke-dasharray="2 3"/><path d="M16 3 16 29" stroke="#9ba89c" stroke-width=".7" stroke-dasharray="2 2"/><g fill="#0f6b5c"><circle cx="8" cy="9" r="3.5"/><circle cx="8" cy="23" r="3.5"/></g><g fill="#577e9c"><circle cx="24" cy="9" r="3.5"/><circle cx="24" cy="23" r="3.5"/></g></svg>'
NAV=[('index.html',['课程','Course']),('foundations/index.html',['基础','Foundations']),('glossary/index.html',['术语','Glossary']),('compare/index.html',['同图比较','Compare']),('progress/index.html',['学习记录','Progress']),('credits/index.html',['资源与贡献','Credits'])]
def page(path,title,body,lang=0,page_type='',module=None):
    actual=('en/' if lang else '')+path
    depth=len(Path(actual).parts)-1
    root='../'*depth or './'
    lr=root+('en/' if lang else '')
    alternate=root+('' if lang else 'en/')+path
    links=''.join(f'<a href="{lr+p}"'+(' aria-current="page"' if p==path else '')+'>'+T(label,lang)+'</a>' for p,label in NAV)
    language=f'<a data-lang-link href="{alternate}" hreflang="'+('zh-CN' if lang else 'en')+'">'+('中文' if lang else 'EN')+'</a>'
    top=f'''<a class="skip" href="#main">{T(['跳到正文','Skip to content'],lang)}</a><header class="topbar"><div class="wrap"><a class="brand" href="{lr}index.html">{LOGO}<span class="brand-name">Learning Partitioning</span></a><nav class="topnav" aria-label="{T(['课程导航','Course navigation'],lang)}">{links}</nav><details class="mobile-nav"><summary>{T(['导航','Menu'],lang)}</summary><nav>{links}</nav></details><button class="icon-button" data-open-search aria-label="{T(['搜索课程','Search the course'],lang)}">⌕ {T(['搜索','Search'],lang)}</button><div class="lang-switch"><span aria-current="true">{'EN' if lang else '中文'}</span>{language}</div></div></header>'''
    module_nav=''
    if module:
        nav=[('goals',['目标','Goals']),('watch',['影片','Watch']),('terms',['术语','Terms']),('reading',['讲义','Lesson']),('slides',['课件','Slides']),('lab',['实验台','Lab']),('challenges',['挑战','Challenges']),('code',['Python','Python']),('mistakes',['易错点','Mistakes']),('resources',['来源','Sources'])]
        module_nav='<nav class="module-nav" aria-label="'+T(['章节导航','Lesson sections'],lang)+'"><div class="wrap">'+''.join(f'<a href="#{anchor}">{T(label,lang)}</a>' for anchor,label in nav)+'</div></nav>'
    footer=f'''<footer class="footer"><div class="wrap"><div><p>Learning Partitioning · {T(['七章 EDA 交互课程，由 FanqinZeng 整合。原作者与改动见','Seven interactive EDA lessons, integrated by FanqinZeng. Original authors and changes:'],lang)} <a href="{lr}credits/index.html">{T(['资源与贡献','Credits'],lang)}</a>。</p><p>{T(['设计与制作规范改编自','Design and production guidance adapted from'],lang)} <a href="https://su3037.github.io/learning-clustering/">Learning Clustering · Su3037</a> · {T(['代码 MIT / 新教材 CC BY 4.0','Code MIT / new course content CC BY 4.0'],lang)}</p></div><p><a href="https://github.com/FanqinZeng/Partitioning_Module_Coordinator">GitHub ↗</a><br><a href="{lr}guide/index.html">{T(['使用指南与离线学习','Guide & offline learning'],lang)}</a><br>2026.11 · v1.0</p></div></footer>'''
    dialog=f'''<dialog id="search-dialog"><div class="dialog-head"><h2>{T(['搜索课程','Search the course'],lang)}</h2><button class="text-button" data-close>{T(['关闭','Close'],lang)} · Esc</button></div><label class="sr-only" for="course-search">{T(['搜索词','Search terms'],lang)}</label><input id="course-search" type="search" placeholder="{T(['割代价、容量、Fiedler…','cut, capacity, Fiedler…'],lang)}" autocomplete="off"><div data-results aria-live="polite"></div></dialog>'''
    script='module.js' if module else 'home.js' if page_type=='home' else 'compare.js' if page_type=='compare' else 'core.js'
    out=f'''<!doctype html><html lang="{'en' if lang else 'zh-CN'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f4f0e7"><title>{E(title)} · Learning Partitioning</title><meta name="description" content="{E(T(['从割代价、初始二分到 KL、FM、谱方法与多路划分：真实交互实验、练习反馈与浏览器 Python。','From cut metrics to KL, FM, spectral and k-way partitioning: real interactive labs, feedback and browser Python.'],lang))}"><link rel="icon" href="{root}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{root}assets/base.css"><link rel="stylesheet" href="{root}assets/partitioning.css"><link rel="alternate" hreflang="{'zh-CN' if lang else 'en'}" href="{alternate}"></head><body data-root="{root}" data-page="{page_type}"{(' data-module="'+module['id']+'"') if module else ''}>{top}{module_nav}<div id="notice" class="notice" role="status" hidden></div><main id="main">{body}</main>{footer}{dialog}<script type="module" src="{root}assets/{script}"></script></body></html>'''
    dest=SITE/actual;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(out)

def home(lang):
    z=lambda x:T(x,lang)
    lr=''
    cards=''.join(f'''<a class="course-card" href="{url(m)}" data-progress-module="{m['id']}"><span class="num">Lesson {m['id']} <span aria-hidden="true">↗</span></span><h3>{E(z(m['title']))}</h3><p>{E(z(m['summary']))}</p><span class="meta">{E(m['author'])} · {m['minutes']} {z(['分钟','min'])}</span><progress value="0" max="10" aria-label="{E(z(m['title']))} {z(['学习进度','progress'])}"></progress><span data-progress-text></span></a>''' for m in CATALOG)
    stages=[(['01 / MEASURE','01 / MEASURE'],['衡量','Measure'],['割代价与约束','Cut cost and constraints']),(['02 / CONSTRUCT','02 / CONSTRUCT'],['构造','Construct'],['初始二分与谱排序','Initial splits and spectral order']),(['03 / REFINE','03 / REFINE'],['改进','Refine'],['KL 与 FM 的试探和回退','KL and FM trials and rollback']),(['04 / EXTEND','04 / EXTEND'],['扩展','Extend'],['递归二分与多路比较','Recursive and k-way comparisons'])]
