    problem=[(['输入','Input'],['小型无向加权图；正面积节点。','A small undirected weighted graph with positive vertex areas.']),(['输出','Output'],['每个节点唯一的组号与可重放事件。','One part label per vertex and a replayable event trace.']),(['目标','Objective'],['评价或降低跨组边权之和。','Evaluate or reduce crossing edge weight.']),(['约束','Constraints'],['二分与平衡按本章声明；人数与面积分别报告。','Use the declared count/balance contract; report counts and areas separately.']),(['假设','Assumptions'],['边每条一次，平票确定；不模拟真实布线。','Each edge once, deterministic ties; no physical routing simulation.']),(['停止','Stop'],[{'metrics':'完成一次评价','initial':'达到目标人数','kl':'无正增益前缀或达到 pass 上限','fm':'无正增益前缀或达到 pass 上限','spectral':'扫描全部合法前缀','recursive':'达到 k 组，或没有合法分裂','multiway':'无正增益合法交换或达到上限'}[m['method']],{'metrics':'After one evaluation','initial':'When target counts are reached','kl':'No positive prefix or pass limit','fm':'No positive prefix or pass limit','spectral':'After sweeping all legal prefixes','recursive':'At k parts or no legal split','multiway':'No improving legal swap or limit'}[m['method']]])]
    fields=''.join('<div><dt>'+z(k)+'</dt><dd>'+z(v)+'</dd></div>' for k,v in problem)
    lesson=''.join(f'<h2 id="{s["id"]}">{E(z(s["title"]))}</h2>'+markdown(z(s['text'])) for s in m['sections'])
