    original_decks=' · '.join(f'<a href="{media[key]}">{label}</a>' for key,label in [('pdf','PDF'),('pptx','PPTX')] if media.get(key))
    if original_decks:body=body.replace('<p><a href="'+source_url+'">','<p>'+z(['作者原课件：','Author’s original slides: '])+original_decks+'</p><p><a href="'+source_url+'">')
    page(path,z(m['title']),body,lang,'module',m)
