def shared_pages(lang):
    z=lambda x:T(x,lang)
    def standard(path,title,lead,content,ptype=''):
        body=f'<section class="wrap page-heading"><p class="eyebrow">LEARNING PARTITIONING / {ptype.upper() or "REFERENCE"}</p><h1>{E(title)}</h1><p class="lead">{lead}</p></section><section class="wrap content-page">{content}</section>'
        page(path,title,body,lang,ptype)
    foundation='''<h2>G01</h2><p>V={A,B,C,D,E}; E={AB:5, AC:1, BC:4, CD:2, CE:1, DE:5}; size(v)=1.</p>'''
    foundation+=f'''<h2>{z(['共同评价器','The shared evaluator'])}</h2><pre>cut = Σ w(u,v) [part(u) ≠ part(v)]\narea[p] = Σ size(v), part(v)=p\nratio = min(area) / max(area)\nimbalance = (max(area) − min(area)) / Σ area</pre><p>{z(['无向边每条一次。节点必须完整互斥，所有目标组非空；capacity 按面积。KL 固定每侧人数，FM 基础轨按人数差检查，谱扫描按人数比例过滤。','Count every undirected edge once. Assign all vertices exactly once; target parts must be nonempty. Capacity uses area. KL fixes side counts, basic FM uses count difference, and spectral sweep uses count fractions.'])}</p><h2>{z(['先修知识','Prerequisites'])}</h2><p>{z(['只需理解加权图、求和、数组与函数。谱方法章节会解释矩阵与特征向量的用途；你可以先使用实验，再阅读推导。','You need weighted graphs, sums, arrays and functions. The spectral lesson explains matrices and eigenvectors; exploring the lab can precede the derivation.'])}</p><h2>{z(['重要区分','Important distinctions'])}</h2><p>{z(['构造产生起点，改进修改起点；试探状态可能变差，接受状态遵守前缀规则；局部停止不证明全局最优；合法性比低 cut 更先检查。','Construction produces a start; refinement modifies it. Trial states can worsen; accepted states follow the prefix rule. A local stop is not a global proof. Check feasibility before rewarding a low cut.'])}</p><p><a href="../modules/02-cut-and-balance/index.html">Lesson 02 →</a></p>'''
    standard('foundations/index.html',z(['基础速查','Foundations']),z(['全课程共享的图、公式与约束。','The graph, formulas and contracts shared across the course.']),foundation)
    terms={}
    for m in CATALOG:
        for term in m['terms']:terms.setdefault(term[0],(term,m))
    glossary='<dl>'+''.join(f'<dt>{E(key)}</dt><dd>{E(term[2] if lang else term[1])} <a href="../{url(m)}#terms">Lesson {m["id"]} ↗</a></dd>' for key,(term,m) in terms.items())+'</dl>'
    standard('glossary/index.html',z(['术语表','Glossary']),z(['中英术语与可回到上下文的解释。按 / 也可以搜索讲义全文。','Bilingual terms with links back to their lessons. Press / to search the complete lesson text.']),glossary)
    guide=f'''<h2>{z(['推荐学习方法','A suggested learning loop'])}</h2><ol><li>{z(['先读目标与术语，确认本章的输入和约束。','Read the goals and terms; identify the input and constraints.'])}</li><li>{z(['在随文实验中先预测下一步，再运行和回退。','Predict the next step in an embedded lab, then run and rewind.'])}</li><li>{z(['完成计算、预测和诊断三类挑战；需要时逐级打开提示。','Attempt computation, prediction and diagnosis challenges, opening hints gradually.'])}</li><li>{z(['实现两个 Python 函数，通过命名检查并解释自己的输出。','Implement two Python functions, pass named checks and explain your output.'])}</li></ol><h2>{z(['学习记录与隐私','Progress and privacy'])}</h2><p>{z(['记录仅保存在当前浏览器，包括代码草稿；没有账号、云同步或成绩上传。阅读需手动标记，实验到达最后一步、挑战答对、代码全部检查通过才分别记录。清理浏览器会删除本地记录，建议定期导出。','Progress and drafts stay in this browser; there is no account, cloud sync or grade upload. Mark reading manually. Reach the last lab step, answer challenges correctly and pass code checks to complete those activities. Export before clearing browser data.'])}</p><h2>{z(['离线学习','Offline learning'])}</h2><p>{z(['下载站点包后解压，用包内 serve.py 启动本地服务器，再在浏览器打开。实验、讲义、搜索和 Python 都使用本地文件；作者托管的原影片与外链仍需网络。直接双击 HTML 会受到浏览器模块与 worker 的限制。','Download and extract the site bundle, run its serve.py local server, then open the printed URL. Lessons, search, labs and Python use local files; author-hosted films and external links still need a connection. Opening HTML directly can block modules and workers.'])}</p><p><a href="{'../../' if lang else '../'}downloads/learning-partitioning-offline.zip">{z(['下载离线站点','Download offline course'])} ↓</a> · <a href="{'../../' if lang else '../'}downloads/partitioning-python.zip">{z(['下载全部 Python 练习','Download all Python exercises'])} ↓</a></p><h2>{z(['键盘与可访问性','Keyboard and accessibility'])}</h2><p>{z(['Tab 导航到按钮和表单；节点换侧支持 Enter/空格；播放、回退与时间轴可用键盘操作。按 / 搜索，Esc 关闭搜索。系统的减少动态设置会关闭界面过渡；算法只在你按播放后自动前进。','Use Tab for controls and forms. Enter or Space moves an interactive vertex. Playback and timeline controls support the keyboard. / opens search; Escape closes it. Reduced-motion preferences disable transitions; automatic stepping starts only when you press Play.'])}</p>'''
    standard('guide/index.html',z(['使用指南','Learning guide']),z(['按自己的节奏阅读、预测、实验和编程。','Read, predict, experiment and code at your own pace.']),guide)
    credits=f'<h2>{z(["七份原提交","The seven original contributions"])}</h2>'
    for m in CATALOG:
        link=f"https://github.com/{m['repo']}/tree/{m['commit']}" if m.get('repo') else m['attachment']
        credits+=f'<h3>Lesson {m["id"]} · {E(z(m["title"]))}</h3><p>{E(m["author"])} · <a href="https://github.com/yongfu-li/eda-learning/issues/{m["issue"]}">Issue #{m["issue"]}</a> · <a href="{m["url"]}">{z(["原页面 / 媒体入口","Original page / media"])}</a> · <a href="{link}">{z(["固定源码版本 / 附件","Pinned source / attachment"])}</a></p>'
    credits+=f'''<h2>{z(['本次整合的实质变化','What this integration changes'])}</h2><p>{z(['统一双语讲义、公共图与评价器；KL/FM 从局部示例扩展为完整 pass、锁定和最佳前缀；递归二分从预设结果改为子图实时求解；多路交换明确与完整 FM 区分。新增随文实验、同图比较、49 道带反馈挑战、浏览器 Python、搜索和可导入导出的学习记录。','The course unifies bilingual lessons, a shared graph and metrics. KL/FM run full passes with locks and rollback. Recursive bisection solves induced subgraphs live. Swap refinement is distinguished from full FM. New features include embedded labs, comparison, 49 feedback challenges, browser Python, search and portable progress.'])}</p><h2>{z(['风格、代码与制作规范','Design, code and production guidance'])}</h2><p><a href="https://github.com/Su3037/learning-clustering/tree/f0b40a2d93283da52813315f1880f263ee3bef0b">Learning Clustering · Su3037</a> {z(['提供 MIT 图工具、KL/FM、谱引擎、基础样式及 CC BY 4.0 course-playbook。本课程保留许可并增加统一适配、校验和新界面。','provides MIT graph utilities, KL/FM/spectral engines and base styles, plus the CC BY 4.0 course-playbook. This course preserves notices and adds adapters, validation and new interfaces.'])}</p><h2>{z(['交互参考','Interaction references'])}</h2><p><a href="https://www.joshwcomeau.com/css/interactive-guide-to-flexbox/">Josh Comeau</a> · <a href="https://www.redblobgames.com/pathfinding/a-star/introduction.html">Red Blob Games</a> · <a href="https://brilliant.org/about/">Brilliant</a> · <a href="https://visualgo.net/en">VisuAlgo</a> · <a href="https://runestone.academy/ns/books/published/thinkcspy/navhelp.html">Runestone</a>。{z(['参考阅读与交互方式，没有复制这些网站的课程代码。','These inform the interaction design; their course code is not copied.'])}</p><h2>{z(['许可与资料边界','Licenses and material scope'])}</h2><p>{z(['新代码 MIT，新教材 CC BY 4.0。原作者影片、课件与教师材料只链接，保留原权利。字体采用 SIL OFL，Pyodide 采用 MPL-2.0 等各自许可。','New code is MIT; new course content is CC BY 4.0. Student films, decks and teacher materials are linked with their rights retained. Fonts use SIL OFL; Pyodide and its components retain their own licenses.'])}</p><h2>{z(['媒体制作状态','Media production status'])}</h2><p>{z(['本版有双语讲义、每章 12 页网页课件和作者原媒体入口。上游 playbook 的每章四部双语新影片、原生 PDF/PPTX 属于进一步制作目标，本版未将它们声明为已完成。','This version includes bilingual lessons, twelve web slides per chapter and author-hosted media links. The upstream playbook’s four newly produced bilingual films per chapter and native PDF/PPTX decks remain further production work and are not claimed as delivered.'])}</p>'''
    standard('credits/index.html',z(['资源与贡献','Sources & credits']),z(['保留每位原作者的署名，让算法、素材与整合修改都可追溯。','Keep every original author credited and trace algorithms, materials and integration changes.']),credits)
    progress=f'''<div id="progress-list"></div><div class="btn-row" style="margin-top:30px"><button class="btn primary" data-export>{z(['导出学习记录','Export progress'])}</button><label class="btn quiet file-label">{z(['导入并替换记录','Import and replace progress'])}<input data-import type="file" accept="application/json,.json"></label><button class="btn quiet" data-reset>{z(['清空记录','Reset progress'])}</button></div><p class="small muted">{z(['只在本浏览器保存，不上传。导入会先校验格式，失败时保留原记录。','Stored only in this browser. Import validates the format before replacing current records.'])}</p><dialog id="reset-dialog"><h2>{z(['清空学习记录？','Reset your progress?'])}</h2><p>{z(['会删除本地完成记录与 Python 草稿。你可以先取消并导出备份。','This removes local completion records and Python drafts. Cancel to export a backup first.'])}</p><div class="btn-row"><button class="btn primary" data-cancel-reset>{z(['取消','Cancel'])}</button><button class="btn quiet" data-confirm-reset>{z(['确认清空','Confirm reset'])}</button></div></dialog>'''
    standard('progress/index.html',z(['学习记录','Your progress']),z(['阅读、实验、挑战与代码分别记录；完成意味着你亲自做过对应动作。','Reading, labs, challenges and code are tracked separately through your actions.']),progress,'progress')
    compare=f'''<div class="compare-page"><p class="compare-note">{z(['二分表固定人数差 ≤1 的对照任务；三路表另列 k 与面积容量。构造过程使用各自声明的规则。精确枚举只在 ≤9 节点、≤4 组时运行。','The bisection table uses a count-difference ≤1 comparison target; the k-way table has its own k and area capacity. Construction follows each stated rule. The exact oracle runs only for ≤9 vertices and ≤4 parts.'])}</p><div class="compare-config"><label>k<input type="number" name="k" min="2" max="6" value="3"></label><label>{z(['面积容量（空=不限）','Area capacity (blank=none)'])}<input type="number" name="capacity" min="0.1" step="0.1" value="2"></label><button class="btn primary" data-compare>{z(['重新比较','Compare again'])}</button></div><p class="compare-error" role="alert" hidden></p><h2>{z(['二分：构造与改进','Bisection: construction and refinement'])}</h2><div data-bisection-table></div><h2>{z(['k 路：构造与交换','k-way: construction and swaps'])}</h2><div data-kway-table></div><p class="compare-note" data-oracle></p><details><summary>{z(['修改同一张图','Edit the shared graph'])}</summary><label for="compare-json">Graph JSON</label><textarea id="compare-json" rows="13" spellcheck="false"></textarea><div class="btn-row"><button class="btn quiet" data-change-weight>{z(['示例：AB 权重改为 1','Example: set AB weight to 1'])}</button><button class="btn quiet" data-reset-graph>{z(['恢复公共图','Restore G01'])}</button></div></details></div>'''
    standard('compare/index.html',z(['同图比较','Compare on one graph']),z(['固定输入，逐项阅读约束，再解释目标差异。不可行的低 cut 不进入有效比较。','Fix the input, read the constraints, then explain the objective differences. An infeasible low cut is not a valid competitor.']),compare,'compare')
    page('404.html',z(['页面未找到','Page not found']),f'<section class="wrap page-heading"><p class="eyebrow">404</p><h1>{z(["这条路径没有课件","This path has no lesson"])}</h1><p style="margin-top:25px"><a href="{("../" if lang else "./")}index.html">{z(["返回课程首页","Return to the course"])}</a></p></section>',lang)

def packages():
    dest=SITE/'downloads';dest.mkdir(exist_ok=True)
    for m in CATALOG:
        with zipfile.ZipFile(dest/f"lesson-{m['id']}-python.zip",'w',zipfile.ZIP_DEFLATED) as z:
            for f in (ROOT/'python'/m['id']).glob('*.py'):z.write(f,f.name)
            z.write(ROOT/'python/checker.py','checker.py')
            z.writestr('README.txt',f"python3 checker.py {m['id']} starter.py\npython3 checker.py {m['id']} reference.py\nEdit the two functions in starter.py. Reference is for comparison.\n")
    with zipfile.ZipFile(dest/'partitioning-python.zip','w',zipfile.ZIP_DEFLATED) as z:
        for f in (ROOT/'python').rglob('*.py'):z.write(f,'python/'+str(f.relative_to(ROOT/'python')))
        z.write(ROOT/'README.md','README.md')
    with zipfile.ZipFile(dest/'learning-partitioning-offline.zip','w',zipfile.ZIP_DEFLATED) as z:
        for f in SITE.rglob('*'):
            if f.is_file() and f.suffix!='.zip':z.write(f,'site/'+str(f.relative_to(SITE)))
        # Include the smaller Python exercise archives; never recursively include this bundle.
        for f in dest.glob('*-python.zip'):z.write(f,'site/downloads/'+f.name)
        z.write(ROOT/'scripts/serve.py','serve.py')
        z.writestr('START-HERE.txt','Run: python3 serve.py\nOpen: http://127.0.0.1:8790/Partitioning_Module_Coordinator/\nOriginal author-hosted media links need an internet connection.\n')

if __name__=='__main__':
    subprocess.run(['python3',str(ROOT/'scripts/create-python-labs.py')],check=True)
    (SITE/'data').mkdir(exist_ok=True)
    (SITE/'data/course.json').write_text(json.dumps(CATALOG,ensure_ascii=False))
    (SITE/'python').mkdir(exist_ok=True)
    shutil.copy(ROOT/'python/checker.py',SITE/'python/checker.py')
    (SITE/'assets/favicon.svg').write_text(LOGO.replace('aria-hidden="true"','xmlns="http://www.w3.org/2000/svg"'))
    (SITE/'assets/posters').mkdir(exist_ok=True)
    for m in CATALOG:
        (SITE/f"assets/posters/{m['id']}.svg").write_text(f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1280 720"><rect width="1280" height="720" fill="#0d2025"/><path d="M850 205 1030 245 950 440 780 425 850 205M850 205 950 440M780 425 1030 245" fill="none" stroke="#415f63" stroke-width="2"/><path d="M950 440 780 425" stroke="#d49b84" stroke-width="3" stroke-dasharray="8 8"/><g fill="#102a2f" stroke="#83bca9" stroke-width="3"><circle cx="850" cy="205" r="30"/><circle cx="1030" cy="245" r="30"/><circle cx="950" cy="440" r="30"/><circle cx="780" cy="425" r="30"/></g><text x="85" y="180" fill="#87c6b1" font-family="monospace" font-size="17" letter-spacing="4">LESSON {m['id']} / ORIGINAL FILM</text><text x="85" y="300" fill="#ece8dc" font-family="serif" font-size="46">{E(m['title'][0])}</text><text x="85" y="365" fill="#a9bab3" font-family="serif" font-size="25">{E(m['title'][1])}</text><path d="M90 520 650 520" stroke="#2b4649"/><text x="85" y="570" fill="#a9bab3" font-family="sans-serif" font-size="18">{E(m['author'])} · EDA Learning / Partitioning</text></svg>''')
    for lang in [0,1]:
        home(lang)
        for m in CATALOG:module_page(m,lang)
        shared_pages(lang)
    (SITE/'.nojekyll').touch()
    packages()
    print('Built 7 lessons × 2 languages; 84 web slides per language; offline and Python packages.')
